/** Fixed member/history and compiled-plan variants; the same authority, identity and accounting gates as E/F. */
@Service
public class RemainingArtifacts {
    private final JdbcTemplate jdbc;private final ObjectMapper json;private final ArtifactRepo records;private final SourceSnapshotReader sources;private final MemberUploadRepo uploads;private final ArtifactService authority;
    private final CollaborationPolicyService policies;private final CollaborationRuntimeClient runtime;private final CollaborationTime time;private final CollaborationStorage storage;private final TransactionTemplate tx;private final CollaborationPages pages;
    public RemainingArtifacts(JdbcTemplate jdbc,ObjectMapper json,ArtifactRepo records,SourceSnapshotReader sources,MemberUploadRepo uploads,ArtifactService authority,CollaborationPolicyService policies,CollaborationRuntimeClient runtime,CollaborationTime time,CollaborationStorage storage,PlatformTransactionManager manager,CollaborationPages pages){this.jdbc=jdbc;this.json=json;this.records=records;this.sources=sources;this.uploads=uploads;this.authority=authority;this.policies=policies;this.runtime=runtime;this.time=time;this.storage=storage;this.tx=new TransactionTemplate(manager);this.pages=pages;}
    private record Fixed(long ws,long project,PolicyReadView policy,ArtifactViews.Source source,ArtifactViews.AccessIdentity access,ObjectNode payload,boolean mock,long deadline) {}
    public boolean accepts(JsonNode request){String kind=request==null?"":request.at("/source/kind").asText();return Set.of("member-upload","member-history","mock").contains(kind);}
    public boolean acceptsConfirmation(long ws,long project,JsonNode request){return jdbc.queryForObject("SELECT COUNT(*) FROM collaboration_previews WHERE id=? AND purpose IS NOT NULL",Long.class,request.path("previewId").asLong())>0||jdbc.queryForObject("SELECT COUNT(*) FROM collaboration_publications WHERE workspace_id=? AND project_id=? AND publication_intent_id=? AND purpose IS NOT NULL",Long.class,ws,project,request.path("publicationIntentId").asText())>0;}
    public record PreviewRequest(JsonNode body,long deadline) {}
    private record RequestBudget(long maximum,long deadline) {}
    public PreviewRequest readRequest(UserAccount actor,String workspace,String project,java.io.InputStream input,Instant started)throws java.io.IOException{
        var budget=tx.execute(status->{long ws=EntityIds.parse(workspace),pid=EntityIds.parse(project);var policy=policies.publicationSnapshot(ws,pid);authority.requireRead(actor,ws,pid,"document");return new RequestBudget(number(policy,MAX_SOURCE_BYTES),started.toEpochMilli()+number(policy,PUBLICATION_OPERATION_TIMEOUT_MS));});
        authority.deadline(budget.deadline());byte[] bytes;try(var output=new java.io.ByteArrayOutputStream()){byte[] buffer=new byte[8192];long total=0;int count;while((count=input.read(buffer,0,(int)Math.min(buffer.length,budget.maximum()-total+1)))!=-1){total+=count;if(total>budget.maximum())throw error(PAYLOAD_TOO_LARGE,"collaboration_upload_size_limit");authority.deadline(budget.deadline());output.write(buffer,0,count);}bytes=output.toByteArray();}
        authority.deadline(budget.deadline());try{JsonNode body=json.reader().with(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).readTree(bytes);authority.deadline(budget.deadline());return new PreviewRequest(body,budget.deadline());}catch(java.io.IOException failure){throw invalid();}
    }
    public Preview preview(UserAccount actor,String workspace,String project,JsonNode command){
        return preview(actor,workspace,project,command,null);
    }
    public Preview preview(UserAccount actor,String workspace,String project,JsonNode command,Long entryDeadline){
        long started=time.now().toEpochMilli();var fixed=tx.execute(status->{long ws=EntityIds.parse(workspace),pid=EntityIds.parse(project);var policy=policies.publicationSnapshot(ws,pid);String kind=command.at("/source/kind").asText();authority.requirePurpose(actor,ws,pid,kind);var request=parsePreview(command);boolean mock=request.source() instanceof ArtifactRequests.Mock;feature(policy,mock,request.includeEvidence());long deadline=entryDeadline==null?started+number(policy,PUBLICATION_OPERATION_TIMEOUT_MS):entryDeadline;authority.deadline(deadline);storage.lockScope(ws,pid);records.lockProject(ws,pid);
            var payload=json.createObjectNode();ArtifactViews.Source source;
            if(request.source() instanceof ArtifactRequests.Mock requested){var document=sources.document(actor,workspace,project,requested.revision(),requested.manifestHash(),number(policy,MAX_SOURCE_BYTES));source=new ArtifactViews.Source("mock",document.version(),document.manifestHash(),json.createObjectNode().put("kind","project"),null);var input=payload.putObject("input").put("maxResponseBytes",number(policy,MAX_MOCK_RESPONSE_BYTES));var files=input.putArray("files");for(var file:document.files())files.addObject().put("path",file.path()).put("content",file.content());payload.set("policy",mockPolicy(policy));}
            else{JsonNode artifact;if(request.source() instanceof ArtifactRequests.Accepted accepted){var fixedUpload=uploads.fixed(ws,pid,EntityIds.parse(accepted.uploadId()),number(policy,MAX_SOURCE_BYTES),false);artifact=records.tree(fixedUpload.body());var meta=fixedUpload.metadata();source=new ArtifactViews.Source("member-history",String.valueOf(meta.id()),meta.digest(),null,null,new ArtifactViews.UploadIdentity(String.valueOf(meta.id()),String.valueOf(meta.actor())),claim(artifact));}
                else{artifact=((ArtifactRequests.Member)request.source()).artifact();source=new ArtifactViews.Source("member-upload",artifact.at("/source/revision").asText(),artifact.at("/source/digest").asText(),null,null,null,claim(artifact));}
                if(!Set.of("report","debug-history").contains(artifact.path("kind").asText())||!artifact.at("/source/trust").asText().equals("member-claim"))throw invalid();payload.putObject("input").put("sourceKind","member-upload").set("artifact",artifact);payload.set("policy",projectionPolicy(policy,request.includeEvidence()));}
            return new Fixed(ws,pid,policy,source,authority.access(actor,ws,pid),payload,mock,deadline);});
        authority.deadline(fixed.deadline());JsonNode output=call(fixed.mock()?"compile-mock":"project-report",fixed.payload(),fixed.deadline(),fixed.policy());JsonNode body;
        if(fixed.mock()){if(!output.path("ok").asBoolean()){boolean deadline=false;for(var item:output.path("diagnostics"))if(item.path("code").asText().equals("SHARED_MOCK_DEADLINE_INVALID"))deadline=true;throw error(deadline?CONFLICT:UNPROCESSABLE_ENTITY,deadline?"mock_deadline_invalid":"mock_compile_failed");}body=output.path("plan");}
        else{body=output;var claim=fixed.source().claim();if(!Set.of("report","debug-history").contains(claim.kind())||!body.path("kind").asText().equals(claim.kind())||!body.at("/source/trust").asText().equals("member-claim")||!body.at("/source/revision").asText().equals(claim.revision())||!body.at("/source/digest").asText().equals(claim.digest()))throw error(BAD_GATEWAY,"publication_projection_mismatch");}
        authority.deadline(fixed.deadline());byte[] bytes=encode(body);if(bytes.length>number(fixed.policy(),MAX_ARTIFACT_BYTES))throw error(CONFLICT,"artifact_size_limit");String digest=Hashes.sha256Hex(bytes);
        return tx.execute(status->{var current=policies.publicationSnapshot(fixed.ws(),fixed.project());authority.requirePurpose(actor,fixed.ws(),fixed.project(),fixed.source().kind());feature(current,fixed.mock(),fixed.payload().at("/policy/includeEvidence").asBoolean());authority.sameAccess(fixed.access(),authority.access(actor,fixed.ws(),fixed.project()));authority.samePolicy(fixed.policy(),current);storage.lockScope(fixed.ws(),fixed.project());records.lockProject(fixed.ws(),fixed.project());verifySource(actor,fixed.ws(),fixed.project(),fixed.source(),current);authority.deadline(fixed.deadline());storage.previewAdmission(actor.id(),fixed.ws(),fixed.project(),current);Instant now=Instant.ofEpochMilli(time.now().toEpochMilli());long id=records.addCandidate(fixed.ws(),fixed.project(),actor.id(),fixed.source(),fixed.access(),fixed.policy(),digest,bytes,now,now.plusMillis(number(current,PREVIEW_TTL_MS)),fixed.deadline());jdbc.update("UPDATE collaboration_previews SET purpose=? WHERE id=?",fixed.source().kind(),id);storage.createdPreview(actor.id(),id,current);
            if(fixed.source().upload()!=null)storage.retain(actor.id(),fixed.ws(),fixed.project(),new StorageTypes.StoredKey(StorageTypes.Kind.UPLOAD,Long.parseLong(fixed.source().upload().uploadId())),StorageTypes.Owner.candidate(id));return preview(records.candidate(id,false,number(current,MAX_ARTIFACT_BYTES)));});
    }
    private ArtifactViews.MemberClaim claim(JsonNode artifact){return new ArtifactViews.MemberClaim(artifact.path("kind").asText(),artifact.at("/source/revision").asText(),artifact.at("/source/digest").asText());}
    public Confirmation confirm(UserAccount actor,String workspace,String project,JsonNode request){long started=time.now().toEpochMilli();return tx.execute(status->{long ws=EntityIds.parse(workspace),pid=EntityIds.parse(project);var policy=policies.publicationSnapshot(ws,pid);authority.requireRead(actor,ws,pid,"document");var command=ArtifactRequests.confirm(request);long deadline=started+number(policy,PUBLICATION_OPERATION_TIMEOUT_MS);authority.deadline(deadline);storage.lockScope(ws,pid);records.lockProject(ws,pid);var old=records.intent(ws,pid,command.publicationIntentId(),number(policy,MAX_ARTIFACT_BYTES));
        if(old!=null){String purpose=jdbc.queryForObject("SELECT purpose FROM collaboration_publications WHERE id=?",String.class,old.id());authority.requirePurpose(actor,ws,pid,purpose);if(old.preview()!=command.previewId()||old.actor()!=actor.id()||!old.digest().equals(command.candidateDigest()))throw error(CONFLICT,"publication_intent_conflict");authority.requireRead(actor,ws,pid,old.kind());return new Confirmation(publication(old),true);}
        var state=records.previewState(command.previewId());if(state==null||state.workspace()!=ws||state.project()!=pid)throw error(NOT_FOUND,"preview_not_found");if(state.receiptRetireAt()!=null)throw error(GONE,"preview_expired");var candidate=records.candidate(command.previewId(),true,number(policy,MAX_ARTIFACT_BYTES));authority.requirePurpose(actor,ws,pid,candidate.source().kind());if(candidate.actor()!=actor.id())throw error(FORBIDDEN,"preview_actor_mismatch");
        if(!candidate.digest().equals(command.candidateDigest())||!candidate.digest().equals(Hashes.sha256Hex(candidate.body())))throw error(CONFLICT,"candidate_digest_mismatch");if(!candidate.state().equals("pending"))throw error(CONFLICT,"preview_not_pending");if(!time.now().isBefore(candidate.expiresAt()))throw error(GONE,"preview_expired");if(command.expectedPolicyRevision()!=candidate.policy().projectionRevision())throw error(CONFLICT,"publication_policy_changed");authority.sameAccess(candidate.access(),authority.access(actor,ws,pid));authority.samePolicy(candidate.policy(),policy);feature(policy,candidate.source().kind().equals("mock"),false);verifySource(actor,ws,pid,candidate.source(),policy);authority.deadline(deadline);storage.versionAdmission(ws,pid,policy);var source=candidate.source();
        if(source.kind().equals("member-upload")){storage.uploadAdmission(ws,pid,policy);JsonNode body=records.tree(candidate.body());long now=time.now().toEpochMilli();long upload=uploads.insert(ws,pid,actor.id(),body.path("kind").asText(),candidate.digest(),body.at("/report/verdict").asText(),candidate.body(),now,now+number(policy,MEMBER_UPLOAD_RETENTION_MS));storage.uploaded(actor.id(),upload,policy);source=new ArtifactViews.Source("member-history",source.revision(),candidate.digest(),null,null,new ArtifactViews.UploadIdentity(String.valueOf(upload),String.valueOf(actor.id())),source.claim());}
        long id=records.publish(candidate,command.publicationIntentId(),Instant.ofEpochMilli(time.now().toEpochMilli()),source);jdbc.update("UPDATE collaboration_publications SET purpose=? WHERE id=?",candidate.source().kind(),id);storage.confirmed(actor.id(),candidate.id(),id,policy);return new Confirmation(publication(records.publication(id,number(policy,MAX_ARTIFACT_BYTES))),false);});}
    public Publication publication(UserAccount actor,long ws,long project,long id){return tx.execute(status->{var policy=policies.publicationSnapshot(ws,project);authority.requireRead(actor,ws,project,"document");storage.lockScope(ws,project);records.lockProject(ws,project);var value=records.publication(id,number(policy,MAX_ARTIFACT_BYTES),head->{scope(head,ws,project);authority.requireRead(actor,ws,project,head.kind());});if(value==null)throw error(NOT_FOUND,"publication_not_found");return publication(value);});}
    Publication publication(ArtifactRepo.Publication value){var body=records.tree(value.body());if(value.kind().equals("mock"))return new MockPublication(String.valueOf(value.id()),value.version(),value.digest(),value.kind(),value.trust(),String.valueOf(value.actor()),value.createdAt().toString(),value.revision(),value.enabled(),source(value.source()),body,body.path("sourceProjectRevision").asText());return new MemberPublication(String.valueOf(value.id()),value.version(),value.digest(),value.kind(),value.trust(),String.valueOf(value.actor()),value.createdAt().toString(),value.revision(),value.enabled(),source(value.source()),body);}
    Preview preview(ArtifactRepo.Candidate value){var body=records.tree(value.body());var constraints=ArtifactConstraints.preview(value.policy());if(value.source().kind().equals("mock"))return new MockPreview(String.valueOf(value.id()),value.state(),value.digest(),value.policy().projectionRevision(),value.expiresAt().toString(),body,source(value.source()),body.path("sourceProjectRevision").asText(),constraints);return new MemberPreview(String.valueOf(value.id()),value.state(),value.digest(),value.policy().projectionRevision(),value.expiresAt().toString(),body,constraints);}
    public Object preview(UserAccount actor,long ws,long project,long id){
        return tx.execute(status->{
            var policy=policies.publicationSnapshot(ws,project);
            authority.requireRead(actor,ws,project,"document");
            storage.lockScope(ws,project);
            records.lockProject(ws,project);
            var state=records.previewState(id);
            if(state==null||state.workspace()!=ws||state.project()!=project)throw error(NOT_FOUND,"preview_not_found");
            if(state.actor()!=actor.id())authority.requirePreviewManagement(actor,ws,project,state.kind());
            if(state.receiptRetireAt()!=null){
                boolean retained=time.now().toEpochMilli()<state.receiptRetireAt();
                throw error(retained?GONE:NOT_FOUND,retained?"preview_expired":"preview_not_found");
            }
            var candidate=records.candidate(id,false,number(policy,MAX_ARTIFACT_BYTES));
            authority.requireRead(actor,ws,project,candidate.source().kind().equals("member-upload")?"report":candidate.source().kind());
            return preview(candidate);
        });
    }
    public Publication patch(UserAccount actor,long ws,long project,long id,JsonNode request){return tx.execute(status->{var policy=policies.publicationSnapshot(ws,project);authority.requireRead(actor,ws,project,"document");storage.lockScope(ws,project);records.lockProject(ws,project);var head=records.head(id,true);scope(head,ws,project);authority.requirePurpose(actor,ws,project,head.kind());fields(request,Set.of("expectedRevision","enabled"));long expected=revision(request);if(!request.path("enabled").isBoolean())throw invalid();cas(head,expected);if(head.revision()==AccessRequests.MAX_REVISION)throw error(CONFLICT,"publication_revision_exhausted");jdbc.update("UPDATE collaboration_publications SET revision=revision+1,enabled=? WHERE id=?",request.path("enabled").booleanValue(),id);storage.publicationUpdated(actor.id(),ws,project,id,policy);return publication(records.publication(id,number(policy,MAX_ARTIFACT_BYTES)));});}
    public void delete(UserAccount actor,long ws,long project,long id,JsonNode request){tx.executeWithoutResult(status->{policies.publicationSnapshot(ws,project);authority.requireRead(actor,ws,project,"document");storage.lockScope(ws,project);records.lockProject(ws,project);var head=records.head(id,true);scope(head,ws,project);authority.requirePurpose(actor,ws,project,head.kind());fields(request,Set.of("expectedRevision"));cas(head,revision(request));storage.removed(actor.id(),ws,project,StorageTypes.Kind.ARTIFACT,id);});}
    public PublicationPage publications(UserAccount actor,long ws,long project,Map<String,String> query){return tx.execute(status->{var policy=policies.publicationSnapshot(ws,project);var decision=authority.requireRead(actor,ws,project,"document");return pages.publications(ws,project,policy,decision.capabilities().contains(Capability.HISTORY_READ),query);});}
    public HistoryPage history(UserAccount actor,long ws,long project,Map<String,String> query){return tx.execute(status->{var policy=policies.publicationSnapshot(ws,project);authority.requireRead(actor,ws,project,"server-report");return pages.history(ws,project,policy,query);});}
    public HistoryBody historyBody(UserAccount actor,String workspace,String project,long id,String source){var fixed=tx.execute(status->{long ws=EntityIds.parse(workspace),pid=EntityIds.parse(project);var policy=policies.publicationSnapshot(ws,pid);authority.requireRead(actor,ws,pid,"server-report");historySource(source);storage.lockScope(ws,pid);records.lockProject(ws,pid);if(source.equals("member-history"))return new HistoryFixed(policy,uploads.fixed(ws,pid,id,number(policy,MAX_ARTIFACT_BYTES),true).body(),null);
            if(jdbc.queryForObject("SELECT COUNT(*) FROM execution_jobs WHERE id=? AND workspace_id=? AND project_id=?",Long.class,id,ws,pid)==0)throw error(NOT_FOUND,"history_not_found");var report=sources.report(actor,workspace,project,String.valueOf(id),number(policy,MAX_SOURCE_BYTES));if(report.reportKind()!=null&&!Set.of("run","stress","debug").contains(report.reportKind()))throw error(UNPROCESSABLE_ENTITY,"source_report_unsupported");return new HistoryFixed(policy,null,report);});
        if(fixed.body()!=null)return new HistoryBody(String.valueOf(id),source,records.tree(fixed.body()));var report=fixed.report();var payload=json.createObjectNode();var input=payload.putObject("input").put("sourceKind","server-archive").put("title","Archived report").put("redaction","unavailable");input.putArray("privateMarkers");input.putObject("source").put("revision",String.valueOf(report.execution())).put("digest",report.hash());input.putObject("report").put("format",report.reportKind()==null?"run":report.reportKind()).set("body",records.tree(report.body()));payload.set("policy",projectionPolicy(fixed.policy(),false));return new HistoryBody(String.valueOf(id),source,call("project-report",payload,time.now().toEpochMilli()+number(fixed.policy(),PUBLICATION_OPERATION_TIMEOUT_MS),fixed.policy()));}
    private record HistoryFixed(PolicyReadView policy,byte[] body,com.autumnharvestc.server.execution.jobs.JobRepo.FixedReport report) {}
    public void deleteHistory(UserAccount actor,long ws,long project,long id,String source){tx.executeWithoutResult(status->{policies.publicationSnapshot(ws,project);var decision=authority.requireRead(actor,ws,project,"server-report");historySource(source);if(!source.equals("member-history"))throw invalid();storage.lockScope(ws,project);records.lockProject(ws,project);var meta=uploads.metadata(id,true);if(meta==null||meta.workspace()!=ws||meta.project()!=project)throw error(NOT_FOUND,"history_not_found");if(meta.actor()!=actor.id()&&!decision.capabilities().contains(Capability.PUBLICATION_MANAGE))throw error(FORBIDDEN,"forbidden");storage.removed(actor.id(),ws,project,StorageTypes.Kind.UPLOAD,id);});}
    private void verifySource(UserAccount actor,long ws,long project,ArtifactViews.Source source,PolicyReadView policy){if(source.kind().equals("mock"))sources.document(actor,String.valueOf(ws),String.valueOf(project),source.revision(),source.digest(),number(policy,MAX_SOURCE_BYTES));else if(source.kind().equals("member-history")){var fixed=uploads.fixed(ws,project,Long.parseLong(source.upload().uploadId()),number(policy,MAX_SOURCE_BYTES),false);if(!fixed.metadata().digest().equals(source.digest())||!String.valueOf(fixed.metadata().actor()).equals(source.upload().uploadedBy()))throw error(CONFLICT,"publication_source_changed");}}
    private void feature(PolicyReadView policy,boolean mock,boolean evidence){authority.feature(policy,!mock,evidence);if(mock&&!allowed(policy,SHARED_MOCK_ALLOWED))throw error(FORBIDDEN,"publication_policy_disabled");}
    private static void scope(ArtifactRepo.PublicationHead head,long ws,long project){if(head==null||head.workspace()!=ws||head.project()!=project)throw error(NOT_FOUND,"publication_not_found");}
    private static void cas(ArtifactRepo.PublicationHead head,long expected){if(head.revision()!=expected)throw error(CONFLICT,"publication_revision_conflict");}
    private static long revision(JsonNode request){try{return AccessRequests.revision(request.get("expectedRevision"));}catch(ApiException problem){throw invalid();}}
    private static void fields(JsonNode request,Set<String> names){try{ArtifactRequests.fields(request,names);}catch(ApiException problem){throw invalid();}}
    private static ArtifactRequests.Preview parsePreview(JsonNode request){try{return ArtifactRequests.preview(request);}catch(ApiException problem){throw invalid();}}
    private static ApiException invalid(){return error(BAD_REQUEST,"invalid_request");}
    private static void historySource(String source){if(source==null||!Set.of("server-report","member-history").contains(source))throw invalid();}
    static Source source(ArtifactViews.Source source){return new Source(source.kind(),source.revision(),source.digest(),source.upload()==null?null:source.upload().uploadId(),source.report()==null?null:source.report().jobId(),source.upload()==null?null:source.upload().uploadedBy());}
    private ObjectNode projectionPolicy(PolicyReadView policy,boolean evidence){var result=json.createObjectNode().put("revision",policy.projectionRevision()).put("includeEvidence",evidence).put("maxFieldBytes",number(policy,MAX_FIELD_BYTES)).put("maxEvidenceBytes",number(policy,MAX_EVIDENCE_BYTES)).put("maxArtifactBytes",number(policy,MAX_ARTIFACT_BYTES));sensitive(policy,result);return result;}
    private ObjectNode mockPolicy(PolicyReadView policy){var result=json.createObjectNode().put("maxResponseBytes",number(policy,MAX_MOCK_RESPONSE_BYTES)).put("maxDelayMs",number(policy,MAX_MOCK_DELAY_MS)).put("requestDeadlineMs",number(policy,MOCK_CALL_TIMEOUT_MS));sensitive(policy,result);return result;}
    private void sensitive(PolicyReadView policy,ObjectNode result){for(var setting:policy.settings())if(setting instanceof PolicyReadView.StringListSetting list&&list.code()!=CORS_ALLOWED_ORIGINS)result.set(list.code().code(),json.valueToTree(list.effective()));}
    private JsonNode call(String operation,JsonNode payload,long deadline,PolicyReadView policy){try{return runtime.call(operation,payload,deadline,Math.toIntExact(number(policy,RPC_MAX_MESSAGE_BYTES)));}catch(CollaborationRuntimeClient.Failure problem){throw problem.code().equals("RPC_INVALID_REQUEST")?invalid():problem.code().equals("RPC_DEADLINE_EXCEEDED")?error(REQUEST_TIMEOUT,"publication_deadline_exceeded"):error(SERVICE_UNAVAILABLE,"collaboration_projection_unavailable");}}
    private static long number(PolicyReadView policy,PolicyReadView.Code code){return CollaborationStorage.number(policy,code);}
    private byte[] encode(JsonNode value){try{return json.writeValueAsBytes(value);}catch(java.io.IOException problem){throw new IllegalStateException(problem);}}
}
